package modelrepo

import "strings"

// ScriptedTestBackendType is the in-binary test backend: its replies are replayed from a script file, never generated by a model.
const ScriptedTestBackendType = "scripted-test"

// CanonicalBackendType maps compatibility backend keywords to the implementation
// type used by the runtime by lowercasing and trimming the input. "local" is a
// documented alias for the llama backend family and must keep canonicalizing to
// it: the backends API advertises "llama (local alias accepted)".
func CanonicalBackendType(backendType string) string {
	normalized := strings.ToLower(strings.TrimSpace(backendType))
	if normalized == "local" {
		return "llama"
	}
	return normalized
}
